@Controller('cloud/instances')
@UseGuards(JwtAuthGuard)
export class CloudInstanceController {
  constructor(private readonly dataSource: DataSource) {}

  @Get(':instanceId/metrics')
  async getMetrics(@Param('instanceId') instanceId: string, @Req() req: AuthenticatedRequest) {
    const instance = await this.dataSource.query(
      'SELECT id FROM vm_instances WHERE id = $1 AND account_id = $2',
      [instanceId, req.user.accountId]
    );
    if (!instance.length) throw new ForbiddenException('Unauthorized access to VM instance telemetry');
    const metrics = await this.dataSource.query(
      'SELECT timestamp, cpu_utilization, memory_usage FROM vm_telemetry WHERE instance_id = $1 ORDER BY timestamp DESC LIMIT 60',
      [instanceId]
    );
    return { instanceId, metrics };
  }
}
